<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import ToolboxPage from '../ToolboxPage.vue'
const router = useRouter(); const nvmState = ref<NvmNodeState>(); const nvmVersionInput = ref(''); const nvmBusy = ref(false); const nvmMessage = ref('读取本机 NVM 的 Node 版本列表。'); const nodeReleases = ref<NodeRelease[]>([]); const nodeReleasesBusy = ref(false); const showAllNvmReleases = ref(false); const nodeReleasesMessage = ref('正在读取 Node.js 官方发布目录；默认仅显示每个主版本的最新 LTS。'); const managerInstallBusy = ref(false); const backToPortal = () => router.push({ name: 'portal' })
const latestLtsNodeReleases = computed(() => { const majors = new Set<string>(); return nodeReleases.value.filter((release) => { if (release.channel !== 'LTS') return false; const major = release.version.split('.')[0]; if (majors.has(major)) return false; majors.add(major); return true }) }); const visibleNodeReleases = computed(() => showAllNvmReleases.value ? nodeReleases.value : latestLtsNodeReleases.value)
const refreshNvmState = async () => { if (!window.nvmTools) return; nvmBusy.value = true; try { nvmState.value = await window.nvmTools.getNodeState(); nvmMessage.value = nvmState.value.installed ? '已读取 NVM 管理的 Node 版本。切换后会影响系统当前启用的 Node。' : `未检测到可用的 NVM：${nvmState.value.error ?? '请确认 nvm 已加入 PATH。'}` } catch (error) { nvmMessage.value = error instanceof Error ? error.message : String(error) } finally { nvmBusy.value = false } }
const refreshNodeReleases = async () => { if (!window.nodeReleaseTools) return; nodeReleasesBusy.value = true; try { nodeReleases.value = await window.nodeReleaseTools.list(); nodeReleasesMessage.value = `已从 Node.js 官方发布目录加载 ${nodeReleases.value.length} 个可安装版本。` } catch (error) { nodeReleasesMessage.value = error instanceof Error ? error.message : String(error) } finally { nodeReleasesBusy.value = false } }
const installNvmNode = async (requestedVersion?: string) => { if (!window.nvmTools) return; const version = (requestedVersion ?? nvmVersionInput.value).trim(); if (!version) { nvmMessage.value = '请输入要安装的 Node 版本。'; return } if (!window.confirm(`NVM 将下载 Node@${version}，是否继续？`)) return; nvmBusy.value = true; try { nvmState.value = await window.nvmTools.installNode(version); nvmVersionInput.value = ''; nvmMessage.value = `Node@${version} 已由 NVM 安装。` } catch (error) { nvmMessage.value = error instanceof Error ? error.message : String(error) } finally { nvmBusy.value = false } }
const useNvmNode = async (version: string) => { if (!window.nvmTools || !window.confirm(`将系统当前 Node 切换到 NVM 的 ${version}，是否继续？`)) return; nvmBusy.value = true; try { nvmState.value = await window.nvmTools.useNode(version); nvmMessage.value = `当前 Node 已切换为 ${nvmState.value.currentVersion ?? version}。` } catch (error) { nvmMessage.value = error instanceof Error ? error.message : String(error) } finally { nvmBusy.value = false } }
const uninstallNvmNode = async (version: string) => { if (!window.nvmTools || !window.confirm(`将永久移除 NVM 管理的 Node@${version}，是否继续？`)) return; nvmBusy.value = true; try { nvmState.value = await window.nvmTools.uninstallNode(version); nvmMessage.value = `Node@${version} 已从 NVM 移除。` } catch (error) { nvmMessage.value = error instanceof Error ? error.message : String(error) } finally { nvmBusy.value = false } }
const installVersionManager = async () => { if (!window.nodeReleaseTools || !window.confirm('将通过 winget 安装 NVM for Windows。安装程序可能要求管理员授权，是否继续？')) return; managerInstallBusy.value = true; try { await window.nodeReleaseTools.installManager('nvm'); await refreshNvmState(); nodeReleasesMessage.value = 'NVM for Windows 安装命令已完成；如界面仍未识别，请重启 LocalForge。' } catch (error) { nodeReleasesMessage.value = error instanceof Error ? error.message : String(error) } finally { managerInstallBusy.value = false } }
void refreshNvmState(); void refreshNodeReleases()
</script>
<template><ToolboxPage><header class="toolbox-heading"><div><p>数据工具 / NVM</p><h2>NVM Node.js 管理</h2><span>直接调用 NVM for Windows；切换版本会改变系统当前启用的 Node。</span></div><button class="back-button" @click="backToPortal">‹ 返回工具列表</button></header><section class="nvm-overview"><div><small>NVM</small><strong>{{ nvmState?.installed ? `v${nvmState.nvmVersion}` : '未检测' }}</strong><span>{{ nvmState?.installed ? '本机 NVM for Windows' : '请确认已安装并加入 PATH' }}</span></div><div><small>当前 NODE</small><strong>{{ nvmState?.currentVersion ? `v${nvmState.currentVersion}` : '—' }}</strong><span>由 <code>nvm use</code> 管理</span></div></section><section class="release-catalog"><header><div><p>NODE.JS RELEASES</p><h3>可下载版本</h3><span>从 Node.js 官方发布目录读取，默认每个主版本仅显示最新长期支持版。</span></div><button :disabled="nodeReleasesBusy" @click="refreshNodeReleases">{{ nodeReleasesBusy ? '读取中…' : '刷新列表' }}</button></header><p class="tool-message">{{ nodeReleasesMessage }}</p><label class="release-filter"><input v-model="showAllNvmReleases" type="checkbox"> 显示近期所有版本 <small>默认显示 {{ latestLtsNodeReleases.length }} 个 LTS 主版本</small></label><div v-if="visibleNodeReleases.length" class="release-list"><div v-for="release in visibleNodeReleases" :key="`${release.channel}-${release.version}`" class="release-row"><code>v{{ release.version }}</code><span :class="`release-channel-${release.channel.toLowerCase().replace(/\s+/g, '-')}`">{{ release.channel }}</span><small>{{ release.channel === 'LTS' ? '长期支持版本' : 'NVM 可安装版本' }}</small><button class="primary" :disabled="nvmBusy || !nvmState?.installed" @click="installNvmNode(release.version)">NVM 安装</button></div></div><p v-else-if="nodeReleases.length" class="empty-state">官方发布目录没有返回 LTS 版本；开启“显示近期所有版本”查看完整列表。</p><div v-if="!nvmState?.installed" class="manager-installs"><span>未检测到 NVM，可通过 winget 安装：</span><button :disabled="managerInstallBusy" @click="installVersionManager">{{ managerInstallBusy ? '正在安装 NVM…' : '安装 NVM for Windows' }}</button></div></section><section class="nvm-actions"><label>Node 版本<input v-model.trim="nvmVersionInput" placeholder="例如 20.19.0 或 22" @keyup.enter="installNvmNode()"></label><button class="primary" :disabled="nvmBusy" @click="installNvmNode()">{{ nvmBusy ? '处理中…' : '安装版本' }}</button><button :disabled="nvmBusy" @click="refreshNvmState">刷新状态</button><p class="tool-message" :class="{ error: nvmState && !nvmState.installed }">{{ nvmMessage }}</p></section><section v-if="nvmState?.installed" class="results-card nvm-versions"><div v-if="nvmState.versions.length" class="nvm-version-list"><div v-for="item in nvmState.versions" :key="item.version" class="nvm-version-row"><code>v{{ item.version }}</code><span v-if="item.isCurrent">当前使用</span><button :disabled="nvmBusy || item.isCurrent" @click="useNvmNode(item.version)">{{ item.isCurrent ? '正在使用' : '切换到此版本' }}</button><button class="danger" :disabled="nvmBusy || item.isCurrent" @click="uninstallNvmNode(item.version)">移除</button></div></div><p v-else class="empty-state">NVM 中暂未安装 Node 版本。</p></section></ToolboxPage></template>
